package app.metrolife;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class ResidentMotionTests {
 @TempDir Path dir;GameService g;String token;long now=1000000000;
 @BeforeEach void setup()throws Exception{ObjectMapper m=new ObjectMapper();g=new GameService(new JsonStore(m,dir.resolve("save.json").toString()),new Content(m),m);g.time=()->now;token=g.guest(null,g.object()).token();g.createWorld(token,g.object().put("mode","solo").put("name","Walking residents"));g.setup(token,g.object().put("city","atl").put("neighborhood","midtown").put("aspiration","founder"));g.players(token,"atl");}
 @Test void surveyedRoutesNeverCrossFootprintsOrWater(){for(String city:new String[]{"atl","nyc","bay"}){assertTrue(g.residentMotion.routes(city).size()>30);for(JsonNode route:g.residentMotion.routes(city)){JsonNode points=route.path("points");for(int i=1;i<points.size();i++){JsonNode a=points.get(i-1),b=points.get(i);double length=Math.hypot(a.get(0).asDouble()-b.get(0).asDouble(),a.get(1).asDouble()-b.get(1).asDouble());int steps=(int)Math.ceil(length/.15);for(int j=0;j<=steps;j++){double t=j/(double)steps,x=a.get(0).asDouble()+(b.get(0).asDouble()-a.get(0).asDouble())*t,z=a.get(1).asDouble()+(b.get(1).asDouble()-a.get(1).asDouble())*t;assertTrue(g.navigation.stand(city,x,z,""),city+" "+route.path("from")+"→"+route.path("to")+" "+x+","+z);}}}}}
 @Test void residentsWalkAtBoundedSpeedEnterLeaveAndPerformActivities(){String wid=g.world(g.session(token,true)).path("id").asText();Map<String,JsonNode> before=new HashMap<>();Set<String> activities=new HashSet<>(),rooms=new HashSet<>();Set<String> entered=new HashSet<>(),left=new HashSet<>();for(int tick=0;tick<800;tick++){now+=200;g.residentMotion.tick();for(JsonNode row:g.community.residents().path(wid)){String id=row.path("userId").asText();JsonNode p=row.path("position"),old=before.put(id,p.deepCopy());activities.add(row.path("activity").asText());if(!p.path("room").isNull()){entered.add(id);rooms.add(p.path("room").asText().split(":")[0]);}else if(entered.contains(id))left.add(id);if(old!=null&&old.path("room").equals(p.path("room"))&&old.path("place").equals(p.path("place")))assertTrue(Math.hypot(old.path("x").asDouble()-p.path("x").asDouble(),old.path("z").asDouble()-p.path("z").asDouble())<=1.1,"NPC did not walk continuously");assertTrue(g.navigation.stand(row.path("city").asText(),p.path("x").asDouble(),p.path("z").asDouble(),p.path("room").asText("")),row.toString());}}assertTrue(rooms.containsAll(List.of("work","cafe","club")),rooms.toString());assertTrue(activities.containsAll(List.of("walk","jog","cheer","sit","type","dance")),activities.toString());assertFalse(left.isEmpty());}
 @Test void journeyPersistsAcrossRestart()throws Exception{g.residentMotion.tick();now+=200;g.residentMotion.tick();g.store.save();GameService restored=new GameService(new JsonStore(g.mapper,g.store.path.toString()),g.content,g.mapper);restored.time=()->now;String wid=g.world(g.session(token,true)).path("id").asText();assertEquals(g.community.residents().path(wid).toString(),restored.community.residents().path(wid).toString());restored.community.touch(restored.world(restored.session(token,true)));now+=200;restored.residentMotion.tick();assertNotEquals(g.community.residents().path(wid).toString(),restored.community.residents().path(wid).toString());}
 @Test void parkApproachesAndLoopsStayOnLandAndActivitiesSpreadAwayFromDoors(){for(String city:new String[]{"atl","nyc","bay"}){var parks=g.residentMotion.data.path("cities").path(city).path("parks").fields();while(parks.hasNext()){var entry=parks.next();JsonNode park=entry.getValue();List<JsonNode> paths=new ArrayList<>();park.path("paths").forEach(paths::add);ArrayNode loop=park.path("loop").deepCopy();loop.add(loop.get(0).deepCopy());paths.add(loop);for(JsonNode path:paths)for(int i=1;i<path.size();i++){JsonNode a=path.get(i-1),b=path.get(i);double dx=b.get(0).asDouble()-a.get(0).asDouble(),dz=b.get(1).asDouble()-a.get(1).asDouble();int steps=Math.max(1,(int)Math.ceil(Math.hypot(dx,dz)/.15));for(int j=0;j<=steps;j++)assertTrue(g.navigation.stand(city,a.get(0).asDouble()+dx*j/steps,a.get(1).asDouble()+dz*j/steps,""),city+" park "+entry.getKey()+" segment "+i+" sample "+j);}}}}
 @Test void automaticNamesRemainUniqueWithoutNumbersBeyondTheOldPool(){Set<String> names=new HashSet<>();for(int i=0;i<700;i++){String name=g.friendlyName();assertTrue(names.add(name));assertFalse(name.matches(".*[0-9].*"),name);g.table("users").putObject("name-test-"+i).put("username",name);}for(JsonNode world:g.community.residents())for(JsonNode n:world)assertFalse(names.contains(n.path("username").asText()));}

}
